mapper.sql:
select m.requester_id, m.business_type from it_missing_report m where m.status='PENDING'
  ${reportScope}
union all
select a.borrower_id, 'OVERDUE_RETURN' from it_asset a
  where a.status='借出中' and a.borrower_id is not null and a.borrow_due < #{supplementDate}
  ${assetScope}
  and not exists (
    select 1 from it_missing_report r
    where r.requester_id=a.borrower_id and r.asset_no=a.no and r.business_type='RETURN' and r.status='PENDING'
  )
  and not exists (
    select 1 from it_asset_request ar
    where ar.asset_no=a.no and ar.type='RETURN' and ar.status in ('PENDING','APPROVED')
      and coalesce(ar.applicant_id, (
        select case when count(*)=1 then min(u.id) end from sys_user u where u.name=ar.applicant
      ))=a.borrower_id
  )

left join (
  select requester_id as supplement_requester_id, 
  from (




  ) pending
  group by requester_id
) supplements
